[
  {
    "question": "In the DBMS syllabus, how is the term **instance** correctly defined?",
    "options": {
      "A": "A collection of tables that together form a database.",
      "B": "A specific set of data values that conform to a database schema at a point in time.",
      "C": "The logical design of the database expressed in ER diagrams.",
      "D": "The set of rules that enforce data integrity."
    },
    "correct_answer": "B",
    "explanation": "The syllabus lists *instance* as the concrete data stored in the database at a particular moment, distinct from the *schema* which describes the structure.",
    "difficulty": "Medium"
  },
  {
    "question": "What primary purpose does the **catalog** serve in a DBMS according to the course description?",
    "options": {
      "A": "It stores user passwords and authentication tokens.",
      "B": "It holds the executable query plans for frequently run statements.",
      "C": "It maintains metadata describing the database’s structure, such as tables, columns, and constraints.",
      "D": "It archives old versions of data for backup and recovery."
    },
    "correct_answer": "C",
    "explanation": "The syllabus mentions the catalog as the repository of metadata (data about data) that describes the database objects, enabling the DBMS to manage and query the schema.",
    "difficulty": "Medium"
  },
  {
    "question": "Which of the following is **NOT** listed as a core component of DBMS architecture in the syllabus?",
    "options": {
      "A": "Query processor",
      "B": "Storage manager",
      "C": "Transaction manager",
      "D": "Network manager"
    },
    "correct_answer": "D",
    "explanation": "The syllabus enumerates query processor, storage manager, transaction manager, recovery manager, and authorization manager. A *Network manager* is not part of the core DBMS components described.",
    "difficulty": "Medium"
  },
  {
    "question": "The syllabus refers to **physical data independence**. Which statement best reflects this concept?",
    "options": {
      "A": "Applications need not be rewritten when the logical schema changes.",
      "B": "Changes to the internal storage structures do not affect the external schema seen by users.",
      "C": "The DBMS automatically encrypts data without user intervention.",
      "D": "Indexes can be added without altering the underlying tables."
    },
    "correct_answer": "B",
    "explanation": "Physical data independence means that modifications to the internal storage (e.g., file organization) are transparent to the external logical view, as defined in the syllabus under data independence topics.",
    "difficulty": "Medium"
  },
  {
    "question": "According to the daily plan, which activity is emphasized **first** for mastering the DBMS Course Syllabus?",
    "options": {
      "A": "Concept review",
      "B": "Most‑asked practice questions",
      "C": "Quiz revision",
      "D": "Laboratory implementation"
    },
    "correct_answer": "A",
    "explanation": "The plan lists *Concept review* as the initial focus point for each study day, followed by practice and quiz revision, ensuring a solid foundation before application.",
    "difficulty": "Medium"
  }
]
